import type { APIContext } from 'astro';
import { buildMirrorMarkdown } from '../lib/mirrors';
import { PAGES, mirrorPathFor, type PageEntry } from '../lib/pages';

// Build-time Markdown mirrors: one .md file per page, generated by Astro
// itself (no post-build script) from the same datasets as the HTML pages.
// "/" -> /index.md, "/x/" -> "/x.md", "/templates/y/" -> "/templates/y.md".
export const prerender = true;

export function getStaticPaths() {
  return PAGES.map((page) => ({
    params: { mirror: mirrorPathFor(page.path).slice(1) },
    props: { page },
  }));
}

export function GET({ props }: APIContext) {
  const page = props.page as PageEntry;
  return new Response(buildMirrorMarkdown(page), {
    headers: { 'content-type': 'text/markdown; charset=UTF-8' },
  });
}
